const inputs = $input.all();

const REQUIRED_VARIANTS = [
  'full_preview',
  'upper_left',
  'center_right',
  'bottom_left'
];

const groups = new Map();
const specifications = new Map();
const jobFiles = new Map();

// Generate a unique identifier for each original image
function getKey(jobId, fileName) {
  return JSON.stringify([jobId, fileName]);
}

// Extract the specification from a source item
function getSpec(source) {
  return source.spec?.data ?? source.data ?? source.spec ?? source;
}

// Extract the original image filename
function getFileName(source) {
  return source.file ??
    (typeof source.data?.files === 'string'
      ? source.data.files
      : null);
}

// Read the original print specifications
for (const item of $('Split images').all()) {

  const source = item.json;
  const spec = getSpec(source);

  const jobId = spec.job_id;
  const fileName = getFileName(source);

  if (!jobId || !fileName) {
    throw new Error('Invalid source specification');
  }

  const key = getKey(jobId, fileName);

  if (specifications.has(key)) {
    throw new Error(
      `Duplicate source image: ${jobId}/${fileName}`
    );
  }

  specifications.set(key, spec);

  if (!jobFiles.has(jobId)) {
    jobFiles.set(jobId, []);
  }

  jobFiles.get(jobId).push(fileName);
}

// Group processed images by job ID and original filename
for (let i = 0; i < inputs.length; i++) {

  const item = inputs[i];
  const data = item.json;

  const jobId = data.job_id;
  const fileName = data.file;
  const variant = data.variant_name;

  if (!jobId || !fileName || !variant) {
    throw new Error(
      `Missing image metadata in item ${i}`
    );
  }

  if (!REQUIRED_VARIANTS.includes(variant)) {
    throw new Error(
      `Unknown image variant: ${variant}`
    );
  }

  if (!item.binary?.data) {
    throw new Error(
      `Missing binary image: ${jobId}/${fileName}/${variant}`
    );
  }

  const key = getKey(jobId, fileName);

  if (!specifications.has(key)) {
    throw new Error(
      `Specification not found: ${jobId}/${fileName}`
    );
  }

  // Create a group for the original image
  if (!groups.has(key)) {
    groups.set(key, {
      job_id: jobId,
      file: fileName,
      report: data,
      variants: {},
      binary: {},
      sourceIndices: []
    });
  }

  const group = groups.get(key);

  // Prevent duplicated image variants
  if (group.variants[variant]) {
    throw new Error(
      `Duplicate variant: ${jobId}/${fileName}/${variant}`
    );
  }

  // Verify consistent technical metadata
  if (
    group.report.width_px !== data.width_px ||
    group.report.height_px !== data.height_px ||
    group.report.status !== data.status
  ) {
    throw new Error(
      `Inconsistent image metadata: ${jobId}/${fileName}`
    );
  }

  // Create metadata describing the image variant
  const variantInfo = {
    name: variant,
    operation: data.operation_type,
    binary_field: variant,
    file_name: item.binary.data.fileName ?? null,
    mime_type: item.binary.data.mimeType ?? null
  };

  if (data.operation_type === 'crop') {

    // Store crop coordinates in original image pixels
    variantInfo.coordinates_px = {
      x: Number(data.crop_x),
      y: Number(data.crop_y)
    };

    variantInfo.dimensions_px = {
      width: Number(data.crop_width),
      height: Number(data.crop_height)
    };

    variantInfo.pixel_scale = 'original';

    variantInfo.purpose =
      'Evaluate sharpness, compression artifacts, ' +
      'pixelation and fine image details';

  } else if (data.operation_type === 'resize') {

    // Store the dimensions of the resized overview
    variantInfo.dimensions_px = {
      width: Number(data.resize_width),
      height: Number(data.resize_height)
    };

    variantInfo.pixel_scale = 'reduced';

    variantInfo.purpose =
      'Evaluate overall composition, visual consistency ' +
      'and large-scale image defects';

  } else {
    throw new Error(
      `Unsupported operation: ${data.operation_type}`
    );
  }

  // Validate image variant dimensions
  const variantW = variantInfo.dimensions_px.width;
  const variantH = variantInfo.dimensions_px.height;

  if (
    !Number.isInteger(variantW) ||
    !Number.isInteger(variantH) ||
    variantW <= 0 ||
    variantH <= 0 ||
    variantW > 768 ||
    variantH > 768
  ) {
    throw new Error(
      `Invalid variant dimensions: ${jobId}/${fileName}/${variant}`
    );
  }

  // Verify that crop coordinates are within image boundaries
  if (data.operation_type === 'crop') {

    const x = variantInfo.coordinates_px.x;
    const y = variantInfo.coordinates_px.y;

    if (
      !Number.isInteger(x) ||
      !Number.isInteger(y) ||
      x < 0 ||
      y < 0 ||
      x + variantW > Number(data.width_px) ||
      y + variantH > Number(data.height_px)
    ) {
      throw new Error(
        `Invalid crop coordinates: ${jobId}/${fileName}/${variant}`
      );
    }
  }

  // Store the image and its metadata
  group.variants[variant] = variantInfo;
  group.binary[variant] = item.binary.data;
  group.sourceIndices.push(i);
}

// Generate the final AI input
const results = [];

for (const group of groups.values()) {

  const key = getKey(group.job_id, group.file);
  const spec = specifications.get(key);

  // Ensure all required images are available
  const missing = REQUIRED_VARIANTS.filter(
    variant => !group.variants[variant]
  );

  if (missing.length > 0) {
    throw new Error(
      `Missing variants for ${group.file}: ${missing.join(', ')}`
    );
  }

  // Prepare original print specifications
  const printSpecification = {
    trim_mm: spec.trim_mm,
    orientation: spec.orientation,
    bleed_mm: spec.bleed_mm,
    min_ppi: spec.min_ppi,
    expected_files: jobFiles.get(group.job_id)
  };

  // Prepare the technical validation report
  const report = group.report;

  const technicalValidation = {
    status: report.status,

    original_dimensions_px: {
      width: report.width_px,
      height: report.height_px
    },

    size_at_300_ppi_mm: report.size_at_300_ppi_mm,

    required_size_mm: report.required_size_mm,

    effective_ppi: {
      x: report.ppi_x,
      y: report.ppi_y
    },

    image_orientation: report.orientation,
    ratio_error_pct: report.ratio_error_pct,
    errors: report.errors ?? []
  };

  // Build the final binary object in a consistent order
  const orderedBinary = {};

  for (const variant of REQUIRED_VARIANTS) {
    orderedBinary[variant] = group.binary[variant];
  }

  results.push({
    json: {
      job_id: group.job_id,
      file: group.file,

      print_specification: printSpecification,

      technical_validation: technicalValidation,

      image_variants: REQUIRED_VARIANTS.map(
        variant => group.variants[variant]
      ),

      analysis_context: {
        images_are_from_same_source: true,
        crop_coordinates_reference: 'original_image',
        crop_pixel_scale: '1:1',
        full_preview_is_resized: true,
        maximum_variant_size_px: 768
      }
    },

    binary: orderedBinary,

    pairedItem: group.sourceIndices.map(
      index => ({ item: index })
    )
  });
}

return results;

