  // Get the technical validation result
  const report = item.json;

  // Get the original print specification
  const source = $('Split images').itemMatching(i).json;
  const spec = source.spec?.data ??
    source.data ??
    source.spec ??
    source;

  // Separate image identification from technical results
  const {
    job_id,
    file,
    ...technicalData
  } = report;

  if (!job_id || !file) {
    throw new Error('Missing job ID or filename');
  }

  return {
    json: {
      job_id,
      file,

      print_specification: {
        trim_mm: spec.trim_mm,
        orientation: spec.orientation,
        bleed_mm: spec.bleed_mm,
        min_ppi: spec.min_ppi
      },

      technical_validation: technicalData,

      ai_validation: {
        execution_status: 'SKIPPED',
        reason: 'TECHNICAL_VALIDATION_FAILED'
      }
    },

    pairedItem: { item: i }
  };
});

const inputs = $input.all();

const OUTPUT_PPI = 300;
const RATIO_TOLERANCE = 0.5;

// Round a number to the specified decimal places
function round(value, decimals = 2) {
  return Number(value.toFixed(decimals));
}

// Extract print specifications from the source item
function getSpec(source) {
  return source.spec?.data ?? source.data ?? source.spec ?? source;
}

// Extract the filename from the Split images node
function getFileName(source) {
  const fileName =
    source.file ??
    (typeof source.data?.files === 'string'
      ? source.data.files
      : null);

  if (typeof fileName !== 'string' || !fileName.trim()) {
    throw new Error('Missing image filename');
  }

  return fileName;
}

// Validate each image independently
return inputs.map((item, i) => {

  // Get the original specification associated with the image
  const source = $('Split images').itemMatching(i).json;
  const spec = getSpec(source);

  const jobId = spec.job_id;
  const fileName = getFileName(source);

  // Get print requirements
  const trimW = Number(spec.trim_mm?.width);
  const trimH = Number(spec.trim_mm?.height);
  const bleed = Number(spec.bleed_mm);
  const minPPI = Number(spec.min_ppi);

  // Get image dimensions in pixels
  const image = item.json;

  const rawWidth = image.size?.width ?? image.width;
  const rawHeight = image.size?.height ?? image.height;

  const width = rawWidth == null ? null : Number(rawWidth);
  const height = rawHeight == null ? null : Number(rawHeight);

  const errors = [];

  let ppiX = null;
  let ppiY = null;
  let ratioError = null;
  let targetW = null;
  let targetH = null;
  let orientation = null;

  // Validate print specifications
  const validSpec =
    Number.isFinite(trimW) && trimW > 0 &&
    Number.isFinite(trimH) && trimH > 0 &&
    Number.isFinite(bleed) && bleed >= 0 &&
    Number.isFinite(minPPI) && minPPI > 0;

  if (!validSpec) {
    errors.push('Invalid print specifications');
  }

  // Validate image dimensions
  const validImage =
    Number.isFinite(width) && width > 0 &&
    Number.isFinite(height) && height > 0;

  if (!validImage) {
    errors.push('Invalid image dimensions');
  }

  // Calculate the physical image dimensions at 300 PPI
  const sizeAt300PPI = {
    width_mm: validImage
      ? round(width * 25.4 / OUTPUT_PPI)
      : null,
    height_mm: validImage
      ? round(height * 25.4 / OUTPUT_PPI)
      : null
  };

  // Validate specification orientation
  if (validSpec) {

    const specOrientation =
      trimW > trimH ? 'landscape' :
      trimH > trimW ? 'portrait' : 'square';

    if (spec.orientation !== specOrientation) {
      errors.push(
        'Specification orientation does not match trim dimensions'
      );
    }

    // Calculate print dimensions including bleed
    targetW = trimW + 2 * bleed;
    targetH = trimH + 2 * bleed;
  }

  // Perform image validation
  if (validSpec && validImage) {

    // Calculate effective print resolution
    ppiX = width * 25.4 / targetW;
    ppiY = height * 25.4 / targetH;

    // Calculate aspect ratio difference
    ratioError = Math.abs(
      (width / height) / (targetW / targetH) - 1
    ) * 100;

    // Determine image orientation
    orientation =
      width > height ? 'landscape' :
      height > width ? 'portrait' : 'square';

    // Calculate required pixel dimensions rounded to whole pixels
    const requiredWidthPx = Math.round(targetW * minPPI / 25.4);
    const requiredHeightPx = Math.round(targetH * minPPI / 25.4);

    // Check minimum resolution with pixel rounding tolerance
    if (width < requiredWidthPx || height < requiredHeightPx) {
      errors.push('Insufficient image resolution');
    }

    // Check aspect ratio
    if (ratioError > RATIO_TOLERANCE) {
      errors.push('Incorrect image aspect ratio');
    }

    // Check image orientation
    if (orientation !== spec.orientation) {
      errors.push('Incorrect image orientation');
    }
  }

  // Return an independent report for each image
  return {
    json: {
      job_id: jobId,
      file: fileName,
      status: errors.length === 0 ? 'PASS' : 'FAIL',

      width_px: validImage ? width : null,
      height_px: validImage ? height : null,

      size_at_300_ppi_mm: sizeAt300PPI,

      required_size_mm: {
        width: targetW,
        height: targetH
      },

      min_ppi: validSpec ? minPPI : null,

      ppi_x: ppiX === null ? null : round(ppiX, 1),
      ppi_y: ppiY === null ? null : round(ppiY, 1),

      orientation,

      ratio_error_pct: ratioError === null
        ? null
        : round(ratioError),

      errors
    },

    // Preserve the connection to the original image item
    pairedItem: { item: i }
  };
});

const inputs = $input.all();

const MAX_CROP_SIZE = 768;
const MAX_PREVIEW_SIDE = 768;

const CROP_POSITIONS = [
  {
    name: 'upper_left',
    xFactor: 0.15,
    yFactor: 0.15
  },
  {
    name: 'center_right',
    xFactor: 0.65,
    yFactor: 0.50
  },
  {
    name: 'bottom_left',
    xFactor: 0.15,
    yFactor: 0.65
  }
];

const results = [];

for (let i = 0; i < inputs.length; i++) {
  const item = inputs[i];

  // Get the original validation report from the IF node
  const image = $('IF - PASS').itemMatching(i).json;

  if (image.status !== 'PASS') {
    continue;
  }

  const width = Number(image.width_px);
  const height = Number(image.height_px);

  if (
    !Number.isFinite(width) ||
    !Number.isFinite(height) ||
    width <= 0 ||
    height <= 0
  ) {
    throw new Error(`Invalid image dimensions: ${image.file}`);
  }

  if (!item.binary?.data) {
    throw new Error(`Missing binary data for file: ${image.file}`);
  }

  // Crop size must never exceed 768 px
  const cropSize = Math.min(
    MAX_CROP_SIZE,
    Math.floor(width),
    Math.floor(height)
  );

  const freeX = width - cropSize;
  const freeY = height - cropSize;

  // Generate 3 crop tasks
  for (const position of CROP_POSITIONS) {
    const cropX = Math.round(freeX * position.xFactor);
    const cropY = Math.round(freeY * position.yFactor);

    results.push({
      json: {
        ...image,
        operation_type: 'crop',
        variant_name: position.name,
        crop_x: cropX,
        crop_y: cropY,
        crop_width: cropSize,
        crop_height: cropSize
      },
      binary: item.binary,
      pairedItem: { item: i }
    });
  }

  // Generate 1 full preview resize task
  let resizeWidth;
  let resizeHeight;

  if (width >= height) {
    resizeWidth = MAX_PREVIEW_SIDE;
    resizeHeight = Math.round(height * MAX_PREVIEW_SIDE / width);
  } else {
    resizeHeight = MAX_PREVIEW_SIDE;
    resizeWidth = Math.round(width * MAX_PREVIEW_SIDE / height);
  }

  results.push({
    json: {
      ...image,
      operation_type: 'resize',
      variant_name: 'full_preview',
      resize_width: resizeWidth,
      resize_height: resizeHeight
    },
    binary: item.binary,
    pairedItem: { item: i }
  });
}

return results;

const expectedJobs = new Map();
const savedJobs = new Map();

// Collect expected files from the original specification
for (const item of $('Split images').all()) {
  const source = item.json;
  const spec = source.data ?? source.spec?.data ?? source.spec ?? source;

  const jobId = spec.job_id;
  const file = source.file;

  if (!jobId || typeof file !== 'string' || !file) {
    throw new Error('Missing job_id or filename in Split images');
  }

  if (!expectedJobs.has(jobId)) {
    expectedJobs.set(jobId, new Set());
  }

  expectedJobs.get(jobId).add(file);
}

// Collect report confirmations from Merge
for (const item of $input.all()) {
  const report = item.json;

  if (!savedJobs.has(report.job_id)) {
    savedJobs.set(report.job_id, []);
  }

  savedJobs.get(report.job_id).push(report);
}

const results = [];

// Check each job independently
for (const [jobId, expectedFiles] of expectedJobs) {
  const reports = savedJobs.get(jobId) ?? [];
  const savedFiles = new Set();

  const failedFiles = [];

  for (const report of reports) {
    if (report.status === true) {
      savedFiles.add(report.file);
    }

    if (report.status !== true || report.analysis_ok !== true) {
      failedFiles.push(report.file);
    }
  }

  const missingFiles = [...expectedFiles].filter(
    file => !savedFiles.has(file)
  );

  const unexpectedFiles = [...savedFiles].filter(
    file => !expectedFiles.has(file)
  );

  const duplicateFiles = [...new Set(
    reports
      .map(report => report.file)
      .filter((file, index, files) => files.indexOf(file) !== index)
  )];

  const completed =
    expectedFiles.size > 0 &&
    missingFiles.length === 0 &&
    unexpectedFiles.length === 0 &&
    duplicateFiles.length === 0 &&
    failedFiles.length === 0;

  results.push({
    json: {
      job_id: jobId,
      status: completed ? 'COMPLETED' : 'ERROR',
      expected_reports: expectedFiles.size,
      saved_reports: savedFiles.size,
      missing_files: missingFiles,
      failed_files: failedFiles,
      unexpected_files: unexpectedFiles,
      duplicate_files: duplicateFiles,
      checked_at: new Date().toISOString()
    }
  });
}

return results;
